 auto& table = slide.shapes().add_table(50, 50, col_widths, row_heights);
 auto& cell = table.rows()[0][0];
 cell.text_frame()->set_text("Bordered");
 auto& fmt = cell.cell_format();
 fmt.border_top().fill_format().set_fill_type(FillType::SOLID);
